.conic-gauge {
    --percentage: 0deg;
    --fill-color: #27ae60;
    width: 120px;
    height: 120px;
    border-radius: 50%;
    background: conic-gradient(var(--fill-color) var(--percentage), #ecf0f1 0);
    display: flex;
    align-items: center;
    justify-content: center;
    margin: 10px auto;
    position: relative;
}

.gauge-text-overlay {
    width: 100px;
    height: 100px;
    background: white;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: bold;
    font-size: 1.2rem;
}

js_code:
window.initGauge = function(card) {
    const gaugeEl = card.querySelector('[id^="dx-gauge-"]');
    if (!gaugeEl) return;
    
    $(gaugeEl).dxCircularGauge({
        scale: {
            startValue: 0, endValue: 100,
            tickInterval: 10,
            label: { customizeText: function (arg) { return arg.valueText + " %"; } }
        },
        rangeContainer: {
            ranges: [
                { startValue: 0, endValue: 30, color: "#e74c3c" },
                { startValue: 30, endValue: 70, color: "#f39c12" },
                { startValue: 70, endValue: 100, color: "#27ae60" }
            ]
        },
        value: 0,
        valueIndicator: { type: "rectangleNeedle", color: "#2c3e50" }
    });
};

window.updateGauge = function(card, val, color) {
    const gaugeEl = card.querySelector('[id^="dx-gauge-"]');
    if (gaugeEl && $(gaugeEl).dxCircularGauge("instance")) {
        $(gaugeEl).dxCircularGauge("instance").value(val);
    }
};

