.simple-bar-gauge-container {
    position: relative;
    height: 30px;
    background: #ecf0f1;
    border-radius: 15px;
    overflow: hidden;
    margin: 15px 0;
    border: 1px solid #ddd;
}

.simple-bar-gauge-fill {
    height: 100%;
    width: 0%;
    transition: width 0.5s ease-in-out, background-color 0.5s;
}

.simple-bar-gauge-text {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    line-height: 30px;
    text-align: center;
    font-weight: bold;
    color: #2c3e50;
}

.bar-trigger {
    position: absolute;
    top: 0;
    bottom: 0;
    width: 2px;
    background-color: #333;
    z-index: 5;
    left: 80%;
    opacity: 0.7;
}

.tank-gauge-container {
    position: relative;
    width: 100px;
    height: 150px;
    background: #f8f9fa;
    border: 3px solid #34495e;
    border-radius: 0 0 10px 10px;
    margin: 10px auto;
    overflow: hidden;
}

.tank-gauge-water {
    position: absolute;
    bottom: 0;
    left: 0;
    right: 0;
    height: 0%;
    background: #3498db;
    transition: height 0.6s cubic-bezier(0.1, 0.7, 1.0, 0.1);
}

.tank-trigger {
    position: absolute;
    left: 0;
    right: 0;
    height: 0;
    border-top: 2px dashed #e74c3c;
    z-index: 5;
    bottom: 80%;
    opacity: 0.6;
}

.three-quarter-wrapper {
    position: relative;
    width: 160px;
    height: 140px;
    margin: 10px auto;
}

.three-quarter-svg {
    width: 100%;
    height: 100%;
}

.gauge-track {
    stroke: #eee;
    stroke-linecap: round;
}

.gauge-fill {
    stroke: #27ae60;
    stroke-linecap: round;
    /* Circumference approx 188.5 for 3/4 circle of R=40 */
    stroke-dasharray: 188.5;
    stroke-dashoffset: 188.5;
    transition: stroke-dashoffset 0.8s cubic-bezier(0.4, 0, 0.2, 1), stroke 0.8s;
}

.gauge-text-overlay {
    position: absolute;
    top: 55%;
    left: 50%;
    transform: translate(-50%, -50%);
    text-align: center;
}

.gauge-text-overlay .value {
    font-size: 2rem;
    font-weight: 800;
    color: #2c3e50;
}

