window.initGauge = function(card) {
    // Inisialisasi awal jika diperlukan
    const fill = card.querySelector('.gauge-fill');
    if (fill) fill.style.strokeDashoffset = 188.5;
};

window.updateGauge = function(card, val, color) {
    const fill = card.querySelector('.gauge-fill');
    const text = card.querySelector('.value');
    
    if (fill) {
        // 188.5 adalah panjang total path 3/4 lingkaran
        const maxOffset = 188.5;
        const offset = maxOffset - (val / 100 * maxOffset);
        
        fill.style.strokeDashoffset = offset;
        fill.style.stroke = color;
    }
    
    if (text) {
        text.textContent = Math.round(val);
        text.style.color = color;
    }
};
